37	/**
38	 * Replaces the home directory with a tilde.
39	 * @param path - The path to tildeify.
40	 * @returns The tildeified path.
41	 */
42	export function tildeifyPath(path: string): string {
43	  const homeDir = homedir();
44	  if (path.startsWith(homeDir)) {
45	    return path.replace(homeDir, '~');
46	  }
47	  return path;
