48	/**
49	 * Deduplicates file paths by file identity (device + inode) rather than string path.
50	 * This is necessary on case-insensitive filesystems where different case variants
51	 * of the same filename resolve to the same physical file but have different path strings.
52	 *
53	 * @param filePaths Array of file paths to deduplicate
54	 * @returns Object containing deduplicated file paths and a map of path to identity key
55	 */
56	export async function deduplicatePathsByFileIdentity(
57	  filePaths: string[],
58	): Promise<{
59	  paths: string[];
60	  identityMap: Map<string, string>;
61	}> {
62	  if (filePaths.length === 0) {
63	    return {
64	      paths: [],
65	      identityMap: new Map<string, string>(),
66	    };
67	  }
68	
69	  // first deduplicate by string path to avoid redundant stat calls
70	  const uniqueFilePaths = Array.from(new Set(filePaths));
71	
72	  const fileIdentityMap = new Map<string, string>();
73	  const deduplicatedPaths: string[] = [];
74	
75	  const CONCURRENT_LIMIT = 20;
76	  const results: Array<{
77	    path: string;
78	    dev: bigint | number | null;
79	    ino: bigint | number | null;
80	  }> = [];
81	
82	  for (let i = 0; i < uniqueFilePaths.length; i += CONCURRENT_LIMIT) {
83	    const batch = uniqueFilePaths.slice(i, i + CONCURRENT_LIMIT);
84	    const batchPromises = batch.map(async (filePath) => {
85	      try {
86	        // use stat() instead of lstat() to follow symlinks and get target file identity
87	        const stats = await fs.stat(filePath);
88	        return {
89	          path: filePath,
90	          dev: stats.dev,
91	          ino: stats.ino,
92	        };
93	      } catch (error: unknown) {
94	        const message = error instanceof Error ? error.message : String(error);
95	        logger.debug(
96	          `could not stat file for deduplication: ${filePath}. error: ${message}`,
97	        );
98	        return {
99	          path: filePath,
100	          dev: null,
101	          ino: null,
102	        };
103	      }
104	    });
105	
106	    const batchResults = await Promise.allSettled(batchPromises);
107	    for (const result of batchResults) {
108	      if (result.status === 'fulfilled') {
109	        results.push(result.value);
110	      } else {
111	        const message = getErrorMessage(result.reason);
112	        debugLogger.debug(
113	          '[DEBUG] [MemoryDiscovery] unexpected error during deduplication stat:',
114	          message,
115	        );
116	      }
117	    }
118	  }
119	
120	  const pathToIdentityMap = new Map<string, string>();
121	  for (const { path, dev, ino } of results) {
122	    if (dev !== null && ino !== null) {
123	      const identityKey = `${dev.toString()}:${ino.toString()}`;
124	      pathToIdentityMap.set(path, identityKey);
125	      if (!fileIdentityMap.has(identityKey)) {
126	        fileIdentityMap.set(identityKey, path);
127	        deduplicatedPaths.push(path);
128	        debugLogger.debug(
129	          '[DEBUG] [MemoryDiscovery] deduplication: keeping',
130	          path,
131	          `(dev: ${dev}, ino: ${ino})`,
132	        );
133	      } else {
134	        const existingPath = fileIdentityMap.get(identityKey);
135	        debugLogger.debug(
136	          '[DEBUG] [MemoryDiscovery] deduplication: skipping',
137	          path,
138	          `(same file as ${existingPath})`,
139	        );
140	      }
141	    } else {
142	      deduplicatedPaths.push(path);
143	    }
144	  }
145	
146	  return {
147	    paths: deduplicatedPaths,
148	    identityMap: pathToIdentityMap,
149	  };
150	}
