152	async function findProjectRoot(
153	  startDir: string,
154	  boundaryMarkers: readonly string[] = ['.git'],
155	): Promise<string | null> {
156	  if (boundaryMarkers.length === 0) {
157	    return null;
158	  }
159	
160	  let currentDir = normalizePath(startDir);
161	  while (true) {
162	    for (const marker of boundaryMarkers) {
163	      // Sanitize: skip markers with path traversal or absolute paths
164	      if (path.isAbsolute(marker) || marker.includes('..')) {
165	        continue;
166	      }
167	      const markerPath = path.join(currentDir, marker);
168	      try {
169	        // Check for existence only — marker can be a directory (normal repos)
170	        // or a file (submodules / worktrees).
171	        await fs.access(markerPath);
172	        return currentDir;
173	      } catch (error: unknown) {
174	        // Don't log ENOENT errors as they're expected when marker doesn't exist
175	        // Also don't log errors in test environments, which often have mocked fs
176	        const isENOENT =
177	          typeof error === 'object' &&
178	          error !== null &&
179	          'code' in error &&
180	          // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
181	          (error as { code: string }).code === 'ENOENT';
182	
183	        // Only log unexpected errors in non-test environments
184	        // process.env['NODE_ENV'] === 'test' or VITEST are common test indicators
185	        const isTestEnv =
186	          process.env['NODE_ENV'] === 'test' || process.env['VITEST'];
187	
188	        if (!isENOENT && !isTestEnv) {
189	          if (typeof error === 'object' && error !== null && 'code' in error) {
190	            // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
191	            const fsError = error as { code: string; message: string };
192	            logger.warn(
193	              `Error checking for ${marker} at ${markerPath}: ${fsError.message}`,
194	            );
195	          } else {
196	            logger.warn(
197	              `Non-standard error checking for ${marker} at ${markerPath}: ${String(error)}`,
198	            );
199	          }
200	        }
201	      }
202	    }
203	    const parentDir = normalizePath(path.dirname(currentDir));
204	    if (parentDir === currentDir) {
205	      return null;
206	    }
207	    currentDir = parentDir;
208	  }
209	}
