50	    const [global, extension, project, userProjectMemory] = await Promise.all([
51	      getGlobalMemoryPaths(),
52	      Promise.resolve(
53	        getExtensionMemoryPaths(this.config.getExtensionLoader()),
54	      ),
55	      this.config.isTrustedFolder()
56	        ? getEnvironmentMemoryPaths(
