146	      return '';
147	    }
148	    const result = await loadJitSubdirectoryMemory(
149	      accessedPath,
150	      trustedRoots,
151	      this.loadedPaths,
152	      this.loadedFileIdentities,
153	      this.config.getMemoryBoundaryMarkers(),
154	    );
155	
156	    if (result.files.length === 0) {
