27	async function resolvePathWithExistingAncestors(
28	  targetPath: string,
29	): Promise<string | undefined> {
30	  const missingSegments: string[] = [];
31	  let currentPath = path.resolve(targetPath);
32	
33	  while (true) {
34	    try {
35	      const realCurrentPath = await fs.realpath(currentPath);
36	      return path.join(realCurrentPath, ...missingSegments.reverse());
37	    } catch (error) {
38	      if (
39	        !isNodeError(error) ||
40	        (error.code !== 'ENOENT' && error.code !== 'ENOTDIR')
41	      ) {
42	        return undefined;
43	      }
44	
45	      const parentPath = path.dirname(currentPath);
46	      if (parentPath === currentPath) {
47	        return undefined;
48	      }
49	
50	      missingSegments.push(path.basename(currentPath));
51	      currentPath = parentPath;
52	    }
53	  }
54	}
