/**
 * A memory inbox patch is considered malformed when any of its hunks declares
 * fewer new-side lines in its header (`@@ -a,b +c,d @@` — the `d` count) than
 * the number of added (`+`) lines the hunk actually contains. Such a patch can
 * never apply cleanly, so it is not surfaced as a reviewable candidate.
 *
 * Unparseable patches (no hunks) are not flagged here — they simply have no
 * hunk that violates the rule.
 */
function isMalformedInboxPatch(patchContent: string): boolean {
  let parsedPatches: StructuredPatch[];
  try {
    parsedPatches = Diff.parsePatch(patchContent);
  } catch {
    return false;
  }

  for (const patch of parsedPatches) {
    for (const hunk of patch.hunks) {
      const addedLines = hunk.lines.filter((line) =>
        line.startsWith('+'),
      ).length;
      if (addedLines > hunk.newLines) {
        return true;
      }
    }
  }

  return false;
}

/**
 * Scans the memory inbox for malformed `.patch` files (see
 * {@link isMalformedInboxPatch}) and deletes them silently — no feedback is
 * emitted for a patch that could never apply. Called before the post-run inbox
 * snapshot so that a run producing only malformed patches records empty
 * `memoryCandidatesCreated` / `memoryFilesUpdated` arrays.
 */
async function removeMalformedInboxPatches(memoryDir: string): Promise<void> {
  for (const kind of ['private', 'global'] as const) {
    const kindRoot = path.join(memoryDir, '.inbox', kind);
    let entries: Array<Dirent<string>>;
    try {
      entries = await fs.readdir(kindRoot, { withFileTypes: true });
    } catch {
      continue;
    }

    for (const entry of entries) {
      if (!entry.isFile() || !entry.name.endsWith('.patch')) {
        continue;
      }

      const fullPath = path.join(kindRoot, entry.name);
      let content: string;
      try {
        content = await fs.readFile(fullPath, 'utf-8');
      } catch {
        continue;
      }

      if (!isMalformedInboxPatch(content)) {
        continue;
      }

      try {
        await fs.unlink(fullPath);
        debugLogger.debug(
          `[MemoryService] Removed malformed inbox patch: ${path.join(kind, entry.name)}`,
        );
      } catch {
        // Best-effort cleanup.
      }
    }
  }
