function isMalformedInboxPatch(patchContent: string): boolean {
  let inHunk = false;
  let declaredNewLines = 0;
  let actualAddedLines = 0;

  const hunkExceedsDeclaration = () =>
    inHunk && actualAddedLines > declaredNewLines;

